function KMScalingTranslation(){this.scaling=new KMScaling(1,1),this.translation=new KMTranslation(0,0)}KMScalingTranslation.prototype.isIdentity=function(){return kmUlits.isFloatEqual(this.scaling.x,0)&&kmUlits.isFloatEqual(this.scaling.y,0)&&this.translation.isEmpty()},KMScalingTranslation.prototype.reset=function(){this.scaling.x=1,this.scaling.y=1,this.translation.empty()},KMScalingTranslation.prototype.getScalingByRelativeRect=function(t,i){var n=0,a=0;kmUlits.isFloatEqual(t.width,i.width)?n=1:n=kmUlits.isFloatEqual(t.width,0)?1:i.width/t.width,kmUlits.isFloatEqual(t.height,i.height)?a=1:a=kmUlits.isFloatEqual(t.height,0)?1:i.height/t.height,this.scaling.x=n,this.scaling.y=a;var s=new KMVector(t.getLocation().x*this.scaling.x,t.getLocation().y*this.scaling.y);return this.translation=i.getLocation().subtract(s),this},KMScalingTranslation.prototype.transformVector=function(t){return t*this.scaling},KMScalingTranslation.prototype.transformAngle=function(t){var i=new KMVector(0,0);return this.transformVector(i.GetRotateVector(t)).getDegreeAngle()},KMScalingTranslation.prototype.transformPoint=function(t){var i=new KMVector(t.x*this.scaling.x,t.y*this.scaling.y);return i.add(this.translation)},KMScalingTranslation.prototype.transformRectangle=function(t){var i=this.transformPoint(t.getLocation()),n=new KMSize(t.getSize().width*this.scaling.x,t.getSize().height*this.scaling.y);return new KMRect(i.x,i.y,n.width,n.height)};
